const labels=['Discipline','Championnat','Catégorie','Saison','Épreuve','Sessions','Publication'];
let step=Math.min(7,Math.max(1,Number(new URLSearchParams(location.search).get('step')||1)));
const data={discipline:'Moto',championship:'MotoGP',category:'Aucune catégorie',season:'2026',event:'Grand Prix de France',circuit:'Circuit Bugatti',sessions:4};
function field(label,value='',type='text',full=false){return `<div class="field ${full?'full':''}"><label>${label}</label><input type="${type}" value="${value}"><span class="hint">Valeur de démonstration — validation selon la spécification.</span></div>`}
function renderSteps(){steps.innerHTML=labels.map((x,i)=>`<div class="step ${i+1<step?'done':''} ${i+1===step?'current':''}">${i+1} ${x}</div>`).join('')}
function render(){renderSteps();prev.disabled=step===1;next.textContent=step===7?'Publier':'Continuer';draft.style.display=step===7?'block':'none';
const pages={
1:`<h2>Étape 1 — Discipline</h2><p class="context">Choisissez une discipline existante ou créez-en une nouvelle.</p><div class="choice selected"><strong>● Sélectionner une discipline existante</strong><p>Moto est sélectionnée.</p></div><div class="choice"><strong>○ Créer une nouvelle discipline</strong><p>Nom, slug, code court et statut.</p></div><div class="grid">${field('Discipline','Moto')}${field('Recherche','Moto')}</div><div class="preview"><small>Aperçu</small><strong>Moto</strong></div>`,
2:`<h2>Étape 2 — Championnat</h2><p class="context">Discipline sélectionnée : Moto</p><div class="choice selected"><strong>● Sélectionner un championnat existant</strong><p>MotoGP est sélectionné.</p></div><div class="choice"><strong>○ Créer un nouveau championnat</strong><p>Nom, slug, code court, ordre et statut.</p></div><div class="grid">${field('Championnat','MotoGP')}${field('Recherche','MotoGP')}</div><div class="preview"><small>Aperçu</small><strong>Moto → MotoGP</strong></div>`,
3:`<h2>Étape 3 — Catégorie facultative</h2><p class="context">Championnat sélectionné : MotoGP</p><div class="choice selected"><strong>● Aucune catégorie</strong><p>La saison sera directement rattachée au championnat.</p></div><div class="choice"><strong>○ Sélectionner une catégorie existante</strong><p><span style="color:#8d6ade">MotoGP · Moto2 · Moto3 · MotoE</span></p></div><div class="choice"><strong>○ Créer une nouvelle catégorie</strong><p>Nom, code, ordre d’affichage et statut.</p></div><div class="preview"><small>Aperçu</small><strong>Moto → MotoGP → Saison 2026</strong></div>`,
4:`<h2>Étape 4 — Saison</h2><p class="context">Branche : Moto → MotoGP → Sans catégorie</p><div class="grid">${field('Libellé','2026')}${field('Fuseau horaire','Europe/Paris')}${field('Année de début','2026','number')}${field('Année de fin','2026','number')}${field('Date de début','2026-01-01','date')}${field('Date de fin','2026-12-31','date')}</div><div class="preview"><small>Aperçu</small><strong>Moto → MotoGP → Saison 2026</strong></div>`,
5:`<h2>Étape 5 — Épreuve et circuit</h2><p class="context">Saison sélectionnée : MotoGP 2026</p><div class="grid">${field('Nom de l’épreuve','Grand Prix de France')}${field('Numéro de manche','6','number')}${field('Début','2026-05-08T09:00','datetime-local')}${field('Fin','2026-05-10T17:00','datetime-local')}${field('Circuit','Circuit Bugatti')}${field('Ville','Le Mans')}${field('Pays','France')}${field('Fuseau horaire','Europe/Paris')}</div>`,
6:`<h2>Étape 6 — Sessions</h2><p class="context">Ajoutez, ordonnez et validez les sessions de l’épreuve.</p><div class="table"><div class="row head"><span>#</span><span>Type</span><span>Nom public</span><span>Début</span><span>Fin</span><span>Statut</span><span>Actions</span></div>${[['1','practice','Essais libres 1','08/05 10:00','08/05 10:45'],['2','qualifying','Qualifications','09/05 10:50','09/05 11:30'],['3','sprint','Course Sprint','09/05 15:00','09/05 15:30'],['4','race','Course','10/05 14:00','10/05 15:00']].map(r=>`<div class="row">${r.map((v,i)=>`<span>${i===5?'<span class="badge">Valide</span>':v}</span>`).join('')}<span>⋯</span></div>`).join('')}</div><button class="btn ghost" style="margin-top:18px">+ Ajouter une session</button>`,
7:`<h2>Étape 7 — Vérification et publication</h2><p class="context">Vérifiez les données avant la publication atomique.</p><div class="summary"><div class="card"><h3>Branche de calendrier</h3><div class="line"><span>Discipline</span><b>Moto</b></div><div class="line"><span>Championnat</span><b>MotoGP</b></div><div class="line"><span>Catégorie</span><b>Sans catégorie</b></div><div class="line"><span>Saison</span><b>2026</b></div><div class="line"><span>Épreuve</span><b>Grand Prix de France</b></div><div class="line"><span>Circuit</span><b>Circuit Bugatti</b></div><div class="line"><span>Sessions</span><b>4</b></div></div><div class="card"><h3>Validation</h3><div class="line"><span>Structure</span><b class="ok">✓ Valide</b></div><div class="line"><span>Dates et fuseaux</span><b class="ok">✓ Valides</b></div><div class="line"><span>Sessions obligatoires</span><b class="ok">✓ Valides</b></div><div class="line"><span>Publication</span><b class="ok">Prête</b></div><p class="hint" style="margin-top:18px">L’opération sera transactionnelle. Aucun fournisseur ne sera affiché dans le contenu public.</p></div></div>`};content.innerHTML=pages[step]}
prev.onclick=()=>{if(step>1){step--;history.replaceState(null,'','?step='+step);render()}};next.onclick=()=>{if(step<7){step++;history.replaceState(null,'','?step='+step);render()}else alert('Maquette : confirmation de publication')};render();
